 "bank.loan.overdue.actionbar": ["§4§lLOAN OVERDUE §r§c%s §7(%s)", "§4§lPINJAMAN TELAT §r§c%s §7(%s)"],
 "bank.loan.err.blocked_withdraw": ["[BANK] §cWithdraw is locked until you repay your overdue loan (%s).", "[BANK] §cTarik uang dikunci sampai pinjaman telat kamu lunas (%s)."],
